#!/usr/bin/env bash
# Nexus-Argo v3.6 — install / uninstall
# Contract: driven by the env vars generated by web/index.html (updateOutputs())
#   NODE_UUID, ARGO_TOKEN, ENABLE_XRAY, XRAY_PORT, XRAY_DOMAIN, XRAY_CONFIGS
#   ENABLE_SINGBOX, SINGBOX_PORT, SINGBOX_DOMAIN, SINGBOX_CONFIGS
#   NODE_PREFIX (old single prefix, fallback only), NODE_PREFIX_ARGO
#   (default "Argo"), NODE_PREFIX_DIRECT (default "直连"): tunnel
#   links use the Argo prefix, direct links use the Direct prefix.
#   Remark format: "<prefix>丨<core>丨<protocol>" for tunnel nodes
#   (e.g. Argo丨Xray丨xhttp_h2); direct nodes are "<prefix>丨<Name>"
#   (e.g. 直连丨Xray-TLS) — the Direct prefix already says 直连,
#   so the middle 直连 segment is dropped. When only NODE_PREFIX
#   is set (old deploy commands), both new prefixes fall back to it;
#   when a new var is set (even empty it falls back, non-empty wins).
#   OPT_ADDRS (comma-separated, default cloudflare.com)
#   SUB_DOMAIN, SUB_PORT (subscription-only service, v3.2 2026-11-19:
#   a tiny Python stdlib server (web/sub-server.py) serving /sub/*
#   on 127.0.0.1:SUB_PORT, reached via one Zero Trust route
#   SUB_DOMAIN -> 127.0.0.1:SUB_PORT. No Worker needed, and
#   ?addrs= live fission works again — the server generates links
#   from the same deploy-command variables, so nothing is synced
#   in a second place. Empty SUB_DOMAIN = skip the sub service.)
#   SUB_PATH (default sub): first path segment of subscription URLs,
#   i.e. https://<SUB_DOMAIN>/<SUB_PATH>/raw/<uuid> — the panel's
#   custom-subscription-address setting.
#   ENABLE_DIRECT (default false): serve nodes straight from the VPS
#   public IP/domain (backup only — exposes the real IP). Direct
#   protocols (each individually checkable, [直连], address =
#   DIRECT_DOMAIN, a separate subdomain from the tunnel domains;
#   direct nodes enter the subscription as-is, never fissioned):
#     Xray:  DIRECT_VLESS_TCP (+_PORT, default 8082, plain TCP, no TLS)
#            DIRECT_VLESS_TLS = DIRECT_XRAY_TLS (+_PORT, default 443, TCP+TLS)
#            DIRECT_VLESS_REALITY (+_PORT, default 9447, TCP+Reality,
#              dest = big-domain SNI, see REALITY_* below)
#            DIRECT_VLESS_WS (+_PORT, default 8083, plain ws, path /ws)
#            DIRECT_VLESS_GRPC (+_PORT, default 8084, gRPC+TLS, serviceName grpc)
#            DIRECT_TROJAN (+_PORT, default 9443, TCP+TLS, password = NODE_UUID)
#            DIRECT_VMESS_WS (+_PORT, default 9444, ws+TLS, path /ws, alterId 0)
#     Sing-box: DIRECT_SB_TLS (+_PORT, default 8443, VLESS+TLS)
#            DIRECT_SB_TROJAN (+_PORT, default 9445, Trojan+TLS, password = NODE_UUID)
#            DIRECT_SS (+_PORT, default 8388, Shadowsocks aes-256-gcm, password = NODE_UUID)
#            DIRECT_HY2 (+_PORT, default 9446, UDP, Hysteria2, password = NODE_UUID,
#              TLS cert, alpn h3)
#   All DIRECT_VLESS_* / DIRECT_TROJAN / DIRECT_VMESS_WS / DIRECT_SB_* /
#   DIRECT_SS / DIRECT_HY2 default false, except DIRECT_VLESS_TLS and
#   DIRECT_SB_TLS which default true (kept from the earlier direct set).
#   Aliases: DIRECT_VLESS_TLS is honoured if set, otherwise
#   DIRECT_XRAY_TLS applies (same for the _PORT variable).
#   直连 VLESS+QUIC 已删除 (2026-11-19): Xray 26.11.9 移除了独立 QUIC
#   传输, 配置测不过; 替代用 HTTP/2 的 gRPC / TLS。
#   CERT_MODE=selfsigned|upload|acme (default selfsigned): how the
#   direct TLS cert at $WORKDIR/direct/cert.pem/key.pem is obtained.
#   selfsigned — generate a 10-year cert only if missing, never overwrite.
#   upload — the panel writes cert.pem/key.pem before deploy; install.sh
#     never overwrites/regenerates when they exist; missing files warn
#     and fall back to selfsigned. acme — try acme.sh standalone http-01
#     on port 80 for DIRECT_DOMAIN (must be a domain, not an IP); on
#     failure warn and fall back to selfsigned, never fail the deploy;
#     on success add a daily `acme.sh --cron` crontab entry (idempotent,
#     only if crontab exists).
#   REALITY_DEST (required when DIRECT_VLESS_REALITY=true): the big
#   domain used as Reality dest/SNI, may carry a port (3X-UI style,
#   e.g. www.microsoft.com:443) — the port is stripped before use;
#   a domain, not an IP. REALITY_SNI overrides the SNI / serverNames
#   when set, otherwise REALITY_DEST is used. REALITY_SHORT_IDS is a
#   comma list of Short IDs (first one goes into the node link);
#   REALITY_MAX_TIME_DIFF (default 0), REALITY_MIN_CLIENT_VER
#   (default 1.0.0), REALITY_MAX_CLIENT_VER (default x.y.z, means
#   no upper limit — omitted from the inbound) are 3X-UI Reality
#   fields, persisted in reality.json.
#   REALITY_PRIVATE_KEY (empty = generate an X25519 keypair and persist
#   it); REALITY_SHORT_ID (empty = `openssl rand -hex 4`, 8 hex chars).
#   Keys persist in $WORKDIR/direct/reality.json and are reused across
#   redeploys when the env vars are empty. No cert is needed for the
#   Reality dest domain. TLS direct links carry allowInsecure=1 unless
#   CERT_MODE=acme (valid cert); plain-TCP / plain-WS links carry none.
#   REALITY_FINGERPRINT (default chrome; only chrome/firefox/safari —
#   the uTLS fingerprints guaranteed to offer the MLKEM key share
#   that Xray >= 26.9.8 Reality servers require).
#   REALITY_FLOW (default xtls-rprx-vision; "none" = no flow).
#   REALITY_ENCRYPTION (default mlkem768x25519plus.native; "none" =
#   no VLESS Encryption layer). This is the VLESS-layer encryption
#   string prefix (method.appearance), NOT a Reality field —
#   realitySettings has no encryption field. VLESS Encryption
#   (mlkem768x25519plus) first shipped stable in Xray-core v25.9.5;
#   this script uses the :latest image (26.11.9 on 2026-11-19,
#   verified against the real binary with `xray -test`), so it is
#   supported. The auth key is X25519-based — the `xray vlessenc`
#   X25519-auth variant (server decryption string
#   mlkem768x25519plus.<appearance>.600s.<32-byte private key>,
#   client encryption string
#   mlkem768x25519plus.<appearance>.0rtt.<32-byte public key>);
#   the ephemeral handshake itself stays ML-KEM-768 + X25519
#   hybrid (post-quantum) either way, so no security is lost vs
#   the ML-KEM-768 auth variant. ML-KEM-768 auth keys (1184-byte,
#   `xray mlkem768`) are NOT used: they need the xray binary at
#   deploy time and bloat every link by ~1.6 KB. The VLESS
#   Encryption keypair is generated with openssl (same X25519 flow
#   as the Reality keys), persisted in reality.json as
#   vless_enc_private_key / vless_enc_public_key, and reused on
#   redeploy. NOTE on clients: Sing-box / Clash (Mihomo) do not
#   support VLESS Encryption — sub-server drops encrypted nodes
#   from format=singbox / format=clash; only Xray-based clients
#   can use the encrypted Reality node (raw/merged base64 keep it).
#   REALITY_SPIDERX (default "/"; only sent in the link as
#   &spiderX= when it is not "/"). Fingerprint / flow /
#   encryption / spiderX persist in reality.json too (env wins
#   when set; the panel passes them on every deploy, so a redeploy
#   never loses them).
#   Direct uses one self-signed cert (clients need allowInsecure=1);
#   direct nodes enter the subscription as-is, never fissioned.
#   TUNNEL_PROTOCOL=auto|http2|quic (default auto)
#   XRAY_CONFIGS / SINGBOX_CONFIGS are comma lists like "xhttp_h1:443,xhttp_h2:443"
#   and "httpupgrade:443,ws:443,grpc:443"
# Frontend defaults: Xray 8001 / xray.yourdomain.com, Sing-box 8002 / singbox.yourdomain.com,
#   client port 443 for every sub-protocol, UUID default 98a9eeea-e34d-4a0b-a151-39ec761d83f6
#   (replace it — see README).
#
# IMPORTANT — known gap vs. the frontend as uploaded (see FRONTEND_CONTRACT.md):
#   The frontend generates every Xray link with path=/ and every Sing-box
#   non-gRPC link with path=/, so there is NO distinct per-protocol path
#   in the client links. This script therefore renders ONE unified inbound
#   per core (Xray 8001, Sing-box 8002), with ALPN / mode / serviceName
#   derived from the selected protocols. Do NOT add a second inbound on
#   the same port — it will fail to bind. If distinct paths are wanted,
#   patch the frontend first (path /xhttp-h1, /xhttp-h2, …) and then
#   render one inbound per path behind a dispatcher.
set -euo pipefail

WORKDIR="/opt/nexus-argo"
REPO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
XRAY_IMAGE="${XRAY_IMAGE:-ghcr.io/xtls/xray-core:latest}"
SINGBOX_IMAGE="${SINGBOX_IMAGE:-ghcr.io/sagernet/sing-box:latest}"
CLOUDFLARED_IMAGE="${CLOUDFLARED_IMAGE:-cloudflare/cloudflared:latest}"
NGINX_IMAGE="${NGINX_IMAGE:-nginx:alpine}"
PYTHON_IMAGE="${PYTHON_IMAGE:-python:3-alpine}"

NODE_UUID="${NODE_UUID:-}"
ARGO_TOKEN="${ARGO_TOKEN:-}"
ENABLE_XRAY="${ENABLE_XRAY:-true}"
XRAY_PORT="${XRAY_PORT:-8001}"
XRAY_DOMAIN="${XRAY_DOMAIN:-xray.yourdomain.com}"
XRAY_CONFIGS="${XRAY_CONFIGS:-xhttp_h1:443,xhttp_h2:443,xhttp_h3:443}"
ENABLE_SINGBOX="${ENABLE_SINGBOX:-true}"
SINGBOX_PORT="${SINGBOX_PORT:-8002}"
SINGBOX_DOMAIN="${SINGBOX_DOMAIN:-singbox.yourdomain.com}"
SINGBOX_CONFIGS="${SINGBOX_CONFIGS:-httpupgrade:443,ws:443,grpc:443}"
# Node prefixes, split (Part A/B contract): tunnel links use the
# Argo prefix, direct links use the Direct prefix. Computed BEFORE
# NODE_PREFIX gets its "Nexus" default, so that an old deploy
# command that only sets NODE_PREFIX still feeds both new vars,
# while a fresh deploy (nothing set) gets Argo / 直连.
NODE_PREFIX_ARGO="${NODE_PREFIX_ARGO:-${NODE_PREFIX:-Argo}}"
NODE_PREFIX_DIRECT="${NODE_PREFIX_DIRECT:-${NODE_PREFIX:-直连}}"
NODE_PREFIX="${NODE_PREFIX:-Nexus}"
# Panel port (nexus-panel, default 2053): install.sh does not start
# the panel, but its port is reserved on this VPS, so direct /
# origin / subscription ports must not take it (same rule as the
# panel backend).
PANEL_PORT="${PANEL_PORT:-2053}"
OPT_ADDRS="${OPT_ADDRS:-cloudflare.com}"
TUNNEL_PROTOCOL="${TUNNEL_PROTOCOL:-auto}"
# Subscription-only service (v3.2): its own domain + port, separate
# from the web panel (127.0.0.1:8080). Serves /sub/raw/<uuid> and
# /sub/merged/<uuid>?addrs=... (base64, live fission, no Worker).
# No second deployment, no env vars to keep in sync — UUID / domains /
# client ports come from this one deploy command only.
# Empty SUB_DOMAIN = skip it.
SUB_DOMAIN="${SUB_DOMAIN:-}"
SUB_PORT="${SUB_PORT:-18080}"
SUB_PATH="${SUB_PATH:-sub}"
# Direct mode (backup only — exposes the VPS real IP). One self-signed
# cert is generated at $WORKDIR/direct/ and shared by the direct inbounds.
ENABLE_DIRECT="${ENABLE_DIRECT:-false}"
DIRECT_DOMAIN="${DIRECT_DOMAIN:-}"
DIRECT_ADDRESS="${DIRECT_ADDRESS:-$DIRECT_DOMAIN}"
DIRECT_DOMAIN="${DIRECT_ADDRESS:-$DIRECT_DOMAIN}"
DIRECT_SNI="${DIRECT_SNI:-}"
DIRECT_XRAY_TLS="${DIRECT_XRAY_TLS:-true}"
DIRECT_XRAY_TLS_PORT="${DIRECT_XRAY_TLS_PORT:-443}"
DIRECT_SB_TLS="${DIRECT_SB_TLS:-true}"
DIRECT_SB_TLS_PORT="${DIRECT_SB_TLS_PORT:-8443}"
# Aliases: DIRECT_VLESS_TLS (and its _PORT var) wins over the
# DIRECT_XRAY_* name when set; otherwise the XRAY name applies.
DIRECT_VLESS_TLS="${DIRECT_VLESS_TLS:-$DIRECT_XRAY_TLS}"
DIRECT_XRAY_TLS="$DIRECT_VLESS_TLS"
DIRECT_VLESS_TLS_PORT="${DIRECT_VLESS_TLS_PORT:-$DIRECT_XRAY_TLS_PORT}"
DIRECT_XRAY_TLS_PORT="$DIRECT_VLESS_TLS_PORT"
# New direct protocols (all default false; only enabled ones render).
DIRECT_VLESS_TCP="${DIRECT_VLESS_TCP:-false}"
DIRECT_VLESS_TCP_PORT="${DIRECT_VLESS_TCP_PORT:-8082}"
DIRECT_VLESS_REALITY="${DIRECT_VLESS_REALITY:-false}"
DIRECT_VLESS_REALITY_PORT="${DIRECT_VLESS_REALITY_PORT:-9447}"
REALITY_DEST="${REALITY_DEST:-}"
REALITY_SNI="${REALITY_SNI:-}"
REALITY_PRIVATE_KEY="${REALITY_PRIVATE_KEY:-}"
REALITY_SHORT_ID="${REALITY_SHORT_ID:-}"
REALITY_SHORT_IDS="${REALITY_SHORT_IDS:-}"
REALITY_MAX_TIME_DIFF="${REALITY_MAX_TIME_DIFF:-}"
REALITY_MIN_CLIENT_VER="${REALITY_MIN_CLIENT_VER:-}"
REALITY_MAX_CLIENT_VER="${REALITY_MAX_CLIENT_VER:-}"
# Reality link params (Part A/B contract; empty = default, applied
# in the Reality setup below after reality.json reuse, so a redeploy
# never loses a previously saved value).
REALITY_FINGERPRINT="${REALITY_FINGERPRINT:-}"
REALITY_FLOW="${REALITY_FLOW:-}"
REALITY_ENCRYPTION="${REALITY_ENCRYPTION:-}"
REALITY_SPIDERX="${REALITY_SPIDERX:-}"
# VLESS Encryption keypair (X25519 auth keys for the Reality node;
# generated with openssl in the Reality setup below when encryption
# is on, persisted in reality.json). The composed strings are
# filled in by the Reality setup below.
REALITY_VLESS_ENC_PRIVATE_KEY="${REALITY_VLESS_ENC_PRIVATE_KEY:-}"
REALITY_VLESS_ENC_PUBLIC_KEY="${REALITY_VLESS_ENC_PUBLIC_KEY:-}"
REALITY_ENC_SERVER="${REALITY_ENC_SERVER:-none}"
REALITY_ENC_CLIENT="${REALITY_ENC_CLIENT:-none}"
DIRECT_VLESS_WS="${DIRECT_VLESS_WS:-false}"
DIRECT_VLESS_WS_PORT="${DIRECT_VLESS_WS_PORT:-8083}"
DIRECT_VLESS_GRPC="${DIRECT_VLESS_GRPC:-false}"
DIRECT_VLESS_GRPC_PORT="${DIRECT_VLESS_GRPC_PORT:-8084}"
DIRECT_TROJAN="${DIRECT_TROJAN:-false}"
DIRECT_TROJAN_PORT="${DIRECT_TROJAN_PORT:-9443}"
DIRECT_VMESS_WS="${DIRECT_VMESS_WS:-false}"
DIRECT_VMESS_WS_PORT="${DIRECT_VMESS_WS_PORT:-9444}"
DIRECT_SB_TROJAN="${DIRECT_SB_TROJAN:-false}"
DIRECT_SB_TROJAN_PORT="${DIRECT_SB_TROJAN_PORT:-9445}"
DIRECT_SS="${DIRECT_SS:-false}"
DIRECT_SS_PORT="${DIRECT_SS_PORT:-8388}"
DIRECT_HY2="${DIRECT_HY2:-false}"
DIRECT_HY2_PORT="${DIRECT_HY2_PORT:-9446}"
CERT_MODE="${CERT_MODE:-selfsigned}"
# 直连 WS path 与 gRPC serviceName: 面板部署时由 panel-server.py
# 每次随机生成经环境变量传进来; 独立部署没传时用公开默认值。
DIRECT_WS_PATH="${DIRECT_WS_PATH:-/ws}"
DIRECT_GRPC_SERVICE="${DIRECT_GRPC_SERVICE:-grpc}"
# Filled in by the cert / Reality setup below (before render); exported
# to the Python render block and to the nexus-sub container.
REALITY_PUBLIC_KEY="${REALITY_PUBLIC_KEY:-}"
# Effective Reality SNI (REALITY_SNI or REALITY_DEST); set below.
REALITY_EFF_SNI="${REALITY_EFF_SNI:-}"

log() { echo "[nexus-argo] $*"; }
die() { echo "[nexus-argo] ERROR: $*" >&2; exit 1; }

# ---- 终端显示: LOGO 横幅 + 分隔线 + 颜色 ----
# 只在终端里生效; 面板里跑部署时输出是管道, 自动退回纯文本,
# 所以面板部署日志里不会出现乱码。NO_COLOR=1 可强制关掉颜色。
if [ -t 1 ] && [ "${NO_COLOR:-}" = "" ]; then
  C_RESET=$'\033[0m'; C_BOLD=$'\033[1m'; C_GREEN=$'\033[1;32m'
  C_YELLOW=$'\033[1;33m'; C_RED=$'\033[1;31m'; C_CYAN=$'\033[1;36m'; C_BLUE=$'\033[1;34m'
else
  C_RESET=''; C_BOLD=''; C_GREEN=''; C_YELLOW=''; C_RED=''; C_CYAN=''; C_BLUE=''
fi
sep() { echo "=================================================================="; }
banner() {
  sep
  echo "${C_CYAN}${C_BOLD}  Nexus-Argo  节点部署${C_RESET}"
  echo "  Argo 隧道 + Xray / Sing-box  |  一次部署, 订阅自动生成"
  sep
}
step() { echo ""; echo "${C_BLUE}▶ $*${C_RESET}"; }
ok()   { echo "${C_GREEN}✔ $*${C_RESET}"; }
warn() { echo "${C_YELLOW}⚠ $*${C_RESET}"; }

is_true() { case "${1,,}" in true|1|yes|y) return 0;; *) return 1;; esac; }

check_port() {
  local name="$1" val="$2"
  [[ "$val" =~ ^[0-9]+$ ]] || die "$name must be a number, got '$val'"
  (( val >= 1 && val <= 65535 )) || die "$name out of range 1-65535: $val"
}

uninstall() {
  log "Uninstalling nexus-* containers and $WORKDIR ..."
  for c in nexus-xray nexus-singbox nexus-sb-dispatch nexus-argo nexus-web-panel nexus-sub; do
    if docker ps -a --format '{{.Names}}' 2>/dev/null | grep -qx "$c"; then
      docker rm -f "$c" >/dev/null || true
      log "removed $c"
    fi
  done
  # Keep the management panel itself (nexus-panel container + $WORKDIR/panel):
  # uninstalling the nodes must not lock the operator out of the panel.
  if [ -d "$WORKDIR/panel" ]; then
    _tmp="$(mktemp -d)"
    mv "$WORKDIR/panel" "$_tmp/panel"
    rm -rf "$WORKDIR"
    mkdir -p "$WORKDIR"
    mv "$_tmp/panel" "$WORKDIR/panel"
    rmdir "$_tmp" 2>/dev/null || true
    log "Kept $WORKDIR/panel (management panel files)"
  else
    rm -rf "$WORKDIR"
  fi
  log "Done. No nexus-* node containers or $WORKDIR remain (panel kept)."
  exit 0
}

[ "${1:-install}" = "uninstall" ] && uninstall

banner
step "步骤 1/5  检查配置"
# ---- validation (mirrors the frontend's validatePort, plus the checks it lacks) ----
[ "$(id -u)" = "0" ] || die "run as root"
command -v docker >/dev/null 2>&1 || die "docker not found — install Docker first (see README)"
command -v python3 >/dev/null 2>&1 || die "python3 not found — needed for JSON rendering"
check_port "XRAY_PORT" "$XRAY_PORT"
check_port "SINGBOX_PORT" "$SINGBOX_PORT"
check_port "SUB_PORT" "$SUB_PORT"
# ---- 端口冲突 (与面板后端同一套规则, 只校验已启用的端口) ----
# 固定保留端口先占位, 启用的端口按顺序加入, 撞上就报错。
# 不能冲突 (同传输层): 面板端口 (PANEL_PORT, 默认 2053)、旧面板
# 8080、系统端口 22 / 80、订阅端口、Xray / Sing-box 回源端口、
# Sing-box 分发器回源+1/+2/+3、直连 TCP 协议端口 (彼此之间及
# 与上述端口之间)。可以共用: 同核心的隧道协议共用一个端口
# (Xray h1/h2/h3 同 443、Sing-box ws/httpupgrade/grpc 同 8443);
# TCP 与 UDP 同号 (如 TCP 443 与 Hy2 UDP 443)。Hysteria2
# 走 UDP, 不参与 TCP 冲突检查 (与面板一致)。
# 只校验已启用的端口: 没启用的核心 / 没勾选的协议, 端口再冲突
# 也不拦部署 (部署时根本不会监听那个端口)。
declare -A _taken=()
_taken["$PANEL_PORT"]="面板端口 $PANEL_PORT"
_taken[8080]="面板端口 8080"
_taken[22]="系统端口 22"
_taken[80]="系统端口 80"
_claim_port() { # _claim_port <port> <label> — 撞上已占用的端口就报错, 否则占位
  local _p="$1" _label="$2"
  if [ -n "${_taken[$_p]:-}" ]; then
    die "$_label $_p 与 ${_taken[$_p]} 冲突, 请更换"
  fi
  _taken[$_p]="$_label"
}
_claim_port "$SUB_PORT" "订阅端口"
if is_true "$ENABLE_XRAY"; then
  _claim_port "$XRAY_PORT" "Xray 回源端口"
fi
# Sing-box dispatcher uses internal ports SINGBOX_PORT+1/+2/+3 (ws/httpupgrade/grpc),
# so the origin port must leave room for them and must not collide with them.
if is_true "$ENABLE_SINGBOX"; then
  (( SINGBOX_PORT <= 65532 )) || die "SINGBOX_PORT must be <= 65532 (dispatcher needs +1/+2/+3): $SINGBOX_PORT"
  _claim_port "$SINGBOX_PORT" "Sing-box 回源端口"
  for _off in 1 2 3; do
    _claim_port "$(( SINGBOX_PORT + _off ))" "Sing-box 分发器内部端口"
  done
fi
[[ "$NODE_UUID" =~ ^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$ ]] \
  || die "NODE_UUID is not a valid UUID: '$NODE_UUID'"
if is_true "$ENABLE_XRAY"; then
  [ -n "$XRAY_CONFIGS" ] || die "Xray enabled but XRAY_CONFIGS is empty"
else
  log "Xray disabled — skipping"
fi
if is_true "$ENABLE_SINGBOX"; then
  [ -n "$SINGBOX_CONFIGS" ] || die "Sing-box enabled but SINGBOX_CONFIGS is empty"
else
  log "Sing-box disabled — skipping"
fi
# Direct mode: nodes served straight from the VPS (self-signed cert,
# clients need allowInsecure=1). TCP direct ports must not collide
# with each other, 8080, or any origin/subscription port; Hysteria2
# is UDP, so its port number is only range-checked (it may share a
# number with a TCP port, e.g. TLS 443 TCP + Hy2 443 UDP).
_is_domain() {
  # A domain: letters/digits/hyphens/dots, at least one dot, not an IPv4 address, no port.
  case "$1" in *:*|*/*) return 1;; esac
  [[ "$1" =~ ^[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?(\.[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?)+$ ]] || return 1
  [[ "$1" =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]] && return 1
  return 0
}
_direct_any=false
if is_true "$ENABLE_DIRECT"; then
  case "$CERT_MODE" in selfsigned|upload|acme) ;; *) die "CERT_MODE must be selfsigned|upload|acme, got '$CERT_MODE'";; esac
  check_port "DIRECT_VLESS_TCP_PORT" "$DIRECT_VLESS_TCP_PORT"
  check_port "DIRECT_XRAY_TLS_PORT" "$DIRECT_XRAY_TLS_PORT"
  check_port "DIRECT_VLESS_REALITY_PORT" "$DIRECT_VLESS_REALITY_PORT"
  check_port "DIRECT_VLESS_WS_PORT" "$DIRECT_VLESS_WS_PORT"
  check_port "DIRECT_VLESS_GRPC_PORT" "$DIRECT_VLESS_GRPC_PORT"
  check_port "DIRECT_TROJAN_PORT" "$DIRECT_TROJAN_PORT"
  check_port "DIRECT_VMESS_WS_PORT" "$DIRECT_VMESS_WS_PORT"
  check_port "DIRECT_SB_TLS_PORT" "$DIRECT_SB_TLS_PORT"
  check_port "DIRECT_SB_TROJAN_PORT" "$DIRECT_SB_TROJAN_PORT"
  check_port "DIRECT_SS_PORT" "$DIRECT_SS_PORT"
  check_port "DIRECT_HY2_PORT" "$DIRECT_HY2_PORT"
  for _flag in DIRECT_VLESS_TCP DIRECT_XRAY_TLS DIRECT_VLESS_REALITY DIRECT_VLESS_WS \
      DIRECT_VLESS_GRPC DIRECT_TROJAN DIRECT_VMESS_WS \
      DIRECT_SB_TLS DIRECT_SB_TROJAN DIRECT_SS DIRECT_HY2; do
    is_true "${!_flag}" && _direct_any=true
  done
  [ "$_direct_any" = "true" ] || die "ENABLE_DIRECT but no direct protocol selected"
  # TCP direct ports: no duplicates among themselves, no collision
  # with the panel / system / subscription / origin / dispatcher
  # ports claimed above (only enabled protocols are checked;
  # Hysteria2 is UDP and never joins this check).
  for _spec in "DIRECT_VLESS_TCP|直连 VLESS TCP|$DIRECT_VLESS_TCP_PORT" \
      "DIRECT_XRAY_TLS|直连 VLESS TLS|$DIRECT_XRAY_TLS_PORT" \
      "DIRECT_VLESS_REALITY|直连 VLESS Reality|$DIRECT_VLESS_REALITY_PORT" \
      "DIRECT_VLESS_WS|直连 VLESS WS|$DIRECT_VLESS_WS_PORT" \
      "DIRECT_VLESS_GRPC|直连 VLESS gRPC|$DIRECT_VLESS_GRPC_PORT" \
      "DIRECT_TROJAN|直连 Trojan|$DIRECT_TROJAN_PORT" \
      "DIRECT_VMESS_WS|直连 VMess WS|$DIRECT_VMESS_WS_PORT" \
      "DIRECT_SB_TLS|直连 Sing-box TLS|$DIRECT_SB_TLS_PORT" \
      "DIRECT_SB_TROJAN|直连 Sing-box Trojan|$DIRECT_SB_TROJAN_PORT" \
      "DIRECT_SS|直连 Shadowsocks|$DIRECT_SS_PORT"; do
    _name="${_spec%%|*}"; _rest="${_spec#*|}"; _label="${_rest%%|*}"; _p="${_rest##*|}"
    is_true "${!_name}" || continue
    _claim_port "$_p" "$_label"
  done
  # Reality: dest must be a domain (not an IP, no port); fingerprint
  # must be one of the three uTLS fingerprints that guarantee the
  # MLKEM key share (panel enforces the same; empty = default chrome,
  # applied in the Reality setup below, so only a non-empty bad value
  # is rejected here).
  if is_true "$DIRECT_VLESS_REALITY"; then
    [ -n "$REALITY_DEST" ] || die "DIRECT_VLESS_REALITY is on but REALITY_DEST is empty — set a big domain (e.g. www.microsoft.com:443)"
    _reality_host="${REALITY_DEST%%:*}"
    _is_domain "$_reality_host" || die "REALITY_DEST must be a domain (not an IP), got '$REALITY_DEST'"
    if [ -n "$REALITY_SNI" ]; then
      _is_domain "$REALITY_SNI" || die "REALITY_SNI must be a domain (not an IP, no port), got '$REALITY_SNI'"
    fi
    if [ -n "$REALITY_FINGERPRINT" ]; then
      case "$REALITY_FINGERPRINT" in chrome|firefox|safari) ;; *)
        die "REALITY_FINGERPRINT 只能是 chrome / firefox / safari, got '$REALITY_FINGERPRINT'" ;;
      esac
    fi
  fi
  if [ -z "$DIRECT_DOMAIN" ]; then
    DIRECT_DOMAIN="$(curl -fsS --max-time 5 https://ifconfig.me/ip 2>/dev/null || curl -fsS --max-time 5 https://api.ipify.org 2>/dev/null || true)"
    [ -n "$DIRECT_DOMAIN" ] || die "ENABLE_DIRECT but DIRECT_DOMAIN is empty and the public IP could not be detected — set DIRECT_DOMAIN"
    log "DIRECT_DOMAIN auto-detected: $DIRECT_DOMAIN"
  fi
  command -v openssl >/dev/null 2>&1 || die "openssl not found — needed for the direct-mode self-signed cert"
fi
if ! is_true "$ENABLE_XRAY" && ! is_true "$ENABLE_SINGBOX" && [ "$_direct_any" != "true" ]; then
  die "at least one core or direct mode must be enabled"
fi
[ -n "$ARGO_TOKEN" ] || log "WARNING: ARGO_TOKEN is empty — tunnel will not start, nodes can still be previewed locally (by design)"
case "$TUNNEL_PROTOCOL" in auto|http2|quic) ;; *) die "TUNNEL_PROTOCOL must be auto|http2|quic, got $TUNNEL_PROTOCOL";; esac

mkdir -p "$WORKDIR"/{xray,singbox,web,sub}
# Direct mode: TLS cert + Reality keys, before render.
# Cert (CERT_MODE): selfsigned — generate a 10-year cert only if
# missing, never overwrite; upload — the panel already wrote
# cert.pem/key.pem, never overwrite/regenerate when present, missing
# files warn and fall back to selfsigned; acme — try acme.sh
# standalone http-01 on port 80, on any failure warn and fall back
# to selfsigned, never fail the deploy; on success add a daily
# `acme.sh --cron` crontab entry (idempotent, only if crontab exists).
# Reality keys persist in $WORKDIR/direct/reality.json and are reused
# across redeploys when REALITY_PRIVATE_KEY / REALITY_SHORT_ID are empty.
_b64url() { python3 -c "import sys,base64; sys.stdout.write(base64.urlsafe_b64encode(sys.stdin.buffer.read()).decode().rstrip('='))"; }
if is_true "$ENABLE_DIRECT"; then
  mkdir -p "$WORKDIR/direct"
  _cert_ok=false
  if [ -f "$WORKDIR/direct/cert.pem" ] && [ -f "$WORKDIR/direct/key.pem" ]; then
    _cert_ok=true
    [ "$CERT_MODE" = "upload" ] && log "直连证书: 使用已上传的证书 ($WORKDIR/direct/cert.pem)"
  fi
  if [ "$CERT_MODE" = "acme" ] && [ "$_cert_ok" = "false" ]; then
    if ! _is_domain "$DIRECT_DOMAIN"; then
      warn "CERT_MODE=acme 但 DIRECT_DOMAIN 不是域名 ($DIRECT_DOMAIN), 无法申请证书 — 回退到自签名证书"
    else
      _acme=""
      if [ -x "$HOME/.acme.sh/acme.sh" ]; then _acme="$HOME/.acme.sh/acme.sh";
      elif command -v acme.sh >/dev/null 2>&1; then _acme="$(command -v acme.sh)"; fi
      if [ -z "$_acme" ]; then
        if command -v timeout >/dev/null 2>&1; then
          timeout 180 curl -fsSL https://get.acme.sh -o /tmp/get.acme.sh 2>/dev/null && sh /tmp/get.acme.sh --install-online >/dev/null 2>&1
        else
          curl -fsSL https://get.acme.sh 2>/dev/null | sh -s -- --install-online >/dev/null 2>&1
        fi
        if [ -x "$HOME/.acme.sh/acme.sh" ]; then _acme="$HOME/.acme.sh/acme.sh"; else warn "acme.sh 安装失败 — 回退到自签名证书"; fi
      fi
      if [ -n "$_acme" ]; then
        if "$_acme" --issue -d "$DIRECT_DOMAIN" --standalone >/dev/null 2>&1 \
           && "$_acme" --install-cert -d "$DIRECT_DOMAIN" \
                --key-file "$WORKDIR/direct/key.pem" \
                --fullchain-file "$WORKDIR/direct/cert.pem" >/dev/null 2>&1 \
           && [ -f "$WORKDIR/direct/cert.pem" ] && [ -f "$WORKDIR/direct/key.pem" ]; then
          _cert_ok=true
          log "ACME 证书已签发 ($DIRECT_DOMAIN)"
          if command -v crontab >/dev/null 2>&1; then
            _cron="0 0 * * * $_acme --cron --home $HOME/.acme.sh > /dev/null 2>&1"
            if ! crontab -l 2>/dev/null | grep -Fq "acme.sh --cron"; then
              (crontab -l 2>/dev/null; echo "$_cron") | crontab - 2>/dev/null \
                && log "ACME 自动续期已加入 crontab (每日检查)" \
                || warn "crontab 写入失败 — ACME 证书不会自动续期, 请手动续期"
            fi
          fi
        else
          warn "ACME 签发失败 (域名 $DIRECT_DOMAIN 需解析到本机且 80 端口可达) — 回退到自签名证书"
        fi
      fi
    fi
  fi
  if [ "$_cert_ok" = "false" ]; then
    [ "$CERT_MODE" = "upload" ] && warn "CERT_MODE=upload 但未找到已上传的证书 — 回退到自签名证书"
    openssl req -x509 -newkey rsa:2048 -keyout "$WORKDIR/direct/key.pem" \
      -out "$WORKDIR/direct/cert.pem" -days 3650 -nodes \
      -subj "/CN=$DIRECT_DOMAIN" >/dev/null 2>&1 \
      || die "自签名证书生成失败 (需要 openssl)"
    log "直连自签名证书已生成 ($WORKDIR/direct/cert.pem, CN=$DIRECT_DOMAIN)"
  fi
  # Reality X25519 keypair (only when the Reality inbound is on).
  # Private key = last 32 bytes of the PKCS#8 DER, public key = last
  # 32 bytes of the SubjectPublicKeyInfo DER, both base64url, no padding.
  if is_true "$DIRECT_VLESS_REALITY"; then
    # 目标可带端口 (3X-UI 式, 如 www.microsoft.com:443): 端口剥掉再用。
    REALITY_DEST="${REALITY_DEST%%:*}"
    REALITY_SNI="${REALITY_SNI%%:*}"
    REALITY_EFF_SNI="${REALITY_SNI:-$REALITY_DEST}"
    _reality_json="$WORKDIR/direct/reality.json"
    # 之前部署的 reality.json: 环境变量没给的值从这里复用 (密钥、
    # 指纹、flow、加密方式、spiderX、VLESS 加密密钥), 环境变量优先。
    if [ -f "$_reality_json" ]; then
      _rj_get() { python3 -c "import json,sys; print(json.load(open(sys.argv[1])).get(sys.argv[2],''))" "$_reality_json" "$1" 2>/dev/null || true; }
      [ -z "$REALITY_PRIVATE_KEY" ] && REALITY_PRIVATE_KEY="$(_rj_get private_key)"
      [ -z "$REALITY_PUBLIC_KEY" ] && REALITY_PUBLIC_KEY="$(_rj_get public_key)"
      [ -z "$REALITY_SHORT_ID" ] && REALITY_SHORT_ID="$(_rj_get short_id)"
      if [ -z "$REALITY_SHORT_IDS" ]; then
        REALITY_SHORT_IDS="$(python3 -c "import json,sys; print(','.join(json.load(open(sys.argv[1])).get('short_ids',[]) or []))" "$_reality_json" 2>/dev/null || true)"
      fi
      [ -z "$REALITY_MAX_TIME_DIFF" ] && REALITY_MAX_TIME_DIFF="$(_rj_get max_time_diff)"
      [ -z "$REALITY_MIN_CLIENT_VER" ] && REALITY_MIN_CLIENT_VER="$(_rj_get min_client_ver)"
      [ -z "$REALITY_MAX_CLIENT_VER" ] && REALITY_MAX_CLIENT_VER="$(_rj_get max_client_ver)"
      [ -z "$REALITY_FINGERPRINT" ] && REALITY_FINGERPRINT="$(_rj_get fingerprint)"
      [ -z "$REALITY_FLOW" ] && REALITY_FLOW="$(_rj_get flow)"
      [ -z "$REALITY_ENCRYPTION" ] && REALITY_ENCRYPTION="$(_rj_get encryption)"
      [ -z "$REALITY_SPIDERX" ] && REALITY_SPIDERX="$(_rj_get spiderx)"
      [ -z "$REALITY_VLESS_ENC_PRIVATE_KEY" ] && REALITY_VLESS_ENC_PRIVATE_KEY="$(_rj_get vless_enc_private_key)"
      [ -z "$REALITY_VLESS_ENC_PUBLIC_KEY" ] && REALITY_VLESS_ENC_PUBLIC_KEY="$(_rj_get vless_enc_public_key)"
      [ -n "$REALITY_PRIVATE_KEY" ] && [ -n "$REALITY_PUBLIC_KEY" ] && log "Reality 密钥已复用 ($WORKDIR/direct/reality.json)"
    fi
    # 默认值 (环境变量与 reality.json 都没给时才用)。
    REALITY_FINGERPRINT="${REALITY_FINGERPRINT:-chrome}"
    REALITY_FLOW="${REALITY_FLOW:-xtls-rprx-vision}"
    REALITY_ENCRYPTION="${REALITY_ENCRYPTION:-mlkem768x25519plus.native}"
    REALITY_SPIDERX="${REALITY_SPIDERX:-/}"
    REALITY_MAX_TIME_DIFF="${REALITY_MAX_TIME_DIFF:-0}"
    REALITY_MIN_CLIENT_VER="${REALITY_MIN_CLIENT_VER:-1.0.0}"
    REALITY_MAX_CLIENT_VER="${REALITY_MAX_CLIENT_VER:-x.y.z}"
    case "$REALITY_MAX_TIME_DIFF" in ''|*[!0-9]*) die "REALITY_MAX_TIME_DIFF 必须是 >= 0 的整数, got '$REALITY_MAX_TIME_DIFF'";; esac
    case "$REALITY_FINGERPRINT" in chrome|firefox|safari) ;; *)
      die "REALITY_FINGERPRINT 只能是 chrome / firefox / safari, got '$REALITY_FINGERPRINT'" ;;
    esac
    # 加密方式只认 mlkem768x25519plus.<外观> 与 none; 其它值警告后
    # 回退到默认 native (面板只会发这两个, 这里是防手写命令写错)。
    case "$REALITY_ENCRYPTION" in
      none|mlkem768x25519plus.native|mlkem768x25519plus.xorpub|mlkem768x25519plus.random) ;;
      *) warn "REALITY_ENCRYPTION 不受支持 ($REALITY_ENCRYPTION) — 回退到 mlkem768x25519plus.native"; REALITY_ENCRYPTION="mlkem768x25519plus.native" ;;
    esac
    if [ -z "$REALITY_PRIVATE_KEY" ]; then
      _priv_pem="$(mktemp)"
      openssl genpkey -algorithm X25519 -out "$_priv_pem" 2>/dev/null \
        || die "Reality X25519 密钥生成失败 (需要 openssl)"
      REALITY_PRIVATE_KEY="$(openssl pkey -in "$_priv_pem" -outform DER 2>/dev/null | tail -c 32 | _b64url)"
      REALITY_PUBLIC_KEY="$(openssl pkey -in "$_priv_pem" -pubout -outform DER 2>/dev/null | tail -c 32 | _b64url)"
      rm -f "$_priv_pem"
      [ -n "$REALITY_PRIVATE_KEY" ] && [ -n "$REALITY_PUBLIC_KEY" ] || die "Reality 密钥派生失败"
    elif [ -z "$REALITY_PUBLIC_KEY" ]; then
      # Private key supplied by env, public key not: derive it from
      # the raw private key via a temporary PKCS#8 PEM.
      _priv_pem="$(mktemp)"
      python3 - "$_priv_pem" "$REALITY_PRIVATE_KEY" <<'PYEOF' || die "Reality 私钥格式错误"
import base64, sys
raw = base64.urlsafe_b64decode(sys.argv[2] + "=" * (-len(sys.argv[2]) % 4))
# PKCS#8 DER for an X25519 key: 302e020100300506032b656e04220420 + 32 raw bytes
der = bytes.fromhex("302e020100300506032b656e04220420") + raw
open(sys.argv[1], "wb").write(b"-----BEGIN PRIVATE KEY-----\n" + base64.encodebytes(der) + b"-----END PRIVATE KEY-----\n")
PYEOF
      REALITY_PUBLIC_KEY="$(openssl pkey -in "$_priv_pem" -pubout -outform DER 2>/dev/null | tail -c 32 | _b64url)"
      rm -f "$_priv_pem"
      [ -n "$REALITY_PUBLIC_KEY" ] || die "Reality 公钥派生失败"
    fi
    [ -n "$REALITY_SHORT_ID" ] || REALITY_SHORT_ID="$(openssl rand -hex 4)"
    [ -n "$REALITY_SHORT_IDS" ] || REALITY_SHORT_IDS="$REALITY_SHORT_ID"
    # VLESS 加密层 (mlkem768x25519plus, 见文件头 REALITY_ENCRYPTION
    # 说明): 与 Reality 密钥分开的另一对 X25519 密钥, openssl 生成、
    # reality.json 持久化、重部署复用。"none" = 不开加密层。
    if [ "$REALITY_ENCRYPTION" = "none" ]; then
      REALITY_ENC_SERVER="none"
      REALITY_ENC_CLIENT="none"
    else
      _enc_app="${REALITY_ENCRYPTION##*.}"   # native / xorpub / random
      if [ -z "$REALITY_VLESS_ENC_PRIVATE_KEY" ]; then
        _venc_pem="$(mktemp)"
        if openssl genpkey -algorithm X25519 -out "$_venc_pem" 2>/dev/null; then
          REALITY_VLESS_ENC_PRIVATE_KEY="$(openssl pkey -in "$_venc_pem" -outform DER 2>/dev/null | tail -c 32 | _b64url)"
          REALITY_VLESS_ENC_PUBLIC_KEY="$(openssl pkey -in "$_venc_pem" -pubout -outform DER 2>/dev/null | tail -c 32 | _b64url)"
        fi
        rm -f "$_venc_pem"
        if [ -z "$REALITY_VLESS_ENC_PRIVATE_KEY" ] || [ -z "$REALITY_VLESS_ENC_PUBLIC_KEY" ]; then
          warn "VLESS 加密密钥生成失败 — Reality 节点不启用加密层 (encryption=none)"
          REALITY_ENCRYPTION="none"
        fi
      elif [ -z "$REALITY_VLESS_ENC_PUBLIC_KEY" ]; then
        # 私钥给了、公钥没给: 从私钥派生 (与 Reality 密钥同一套办法)。
        _venc_pem="$(mktemp)"
        python3 - "$_venc_pem" "$REALITY_VLESS_ENC_PRIVATE_KEY" <<'PYEOF' || die "VLESS 加密私钥格式错误"
import base64, sys
raw = base64.urlsafe_b64decode(sys.argv[2] + "=" * (-len(sys.argv[2]) % 4))
# PKCS#8 DER for an X25519 key: 302e020100300506032b656e04220420 + 32 raw bytes
der = bytes.fromhex("302e020100300506032b656e04220420") + raw
open(sys.argv[1], "wb").write(b"-----BEGIN PRIVATE KEY-----\n" + base64.encodebytes(der) + b"-----END PRIVATE KEY-----\n")
PYEOF
        REALITY_VLESS_ENC_PUBLIC_KEY="$(openssl pkey -in "$_venc_pem" -pubout -outform DER 2>/dev/null | tail -c 32 | _b64url)"
        rm -f "$_venc_pem"
        if [ -z "$REALITY_VLESS_ENC_PUBLIC_KEY" ]; then
          warn "VLESS 加密公钥派生失败 — Reality 节点不启用加密层 (encryption=none)"
          REALITY_ENCRYPTION="none"
        fi
      fi
      if [ "$REALITY_ENCRYPTION" != "none" ]; then
        # 与 `xray vlessenc` 的 X25519 鉴权输出同一格式 (实测
        # Xray 26.11.9: decryption …600s.<私钥>, encryption
        # …0rtt.<公钥>; 无 padding 块时核心自动用默认 padding)。
        REALITY_ENC_SERVER="mlkem768x25519plus.${_enc_app}.600s.${REALITY_VLESS_ENC_PRIVATE_KEY}"
        REALITY_ENC_CLIENT="mlkem768x25519plus.${_enc_app}.0rtt.${REALITY_VLESS_ENC_PUBLIC_KEY}"
        log "VLESS 加密层已启用 ($REALITY_ENCRYPTION, 仅 Xray 系客户端可用)"
      else
        REALITY_ENC_SERVER="none"
        REALITY_ENC_CLIENT="none"
      fi
    fi
    python3 - "$_reality_json" "$REALITY_PRIVATE_KEY" "$REALITY_PUBLIC_KEY" "$REALITY_SHORT_ID" "$REALITY_DEST" \
      "$REALITY_FINGERPRINT" "$REALITY_FLOW" "$REALITY_ENCRYPTION" "$REALITY_SPIDERX" \
      "$REALITY_VLESS_ENC_PRIVATE_KEY" "$REALITY_VLESS_ENC_PUBLIC_KEY" \
      "$REALITY_SHORT_IDS" "$REALITY_MAX_TIME_DIFF" "$REALITY_MIN_CLIENT_VER" "$REALITY_MAX_CLIENT_VER" <<'PYEOF'
import json, sys
with open(sys.argv[1], "w") as f:
    json.dump({"private_key": sys.argv[2], "public_key": sys.argv[3],
               "short_id": sys.argv[4], "dest": sys.argv[5],
               "fingerprint": sys.argv[6], "flow": sys.argv[7],
               "encryption": sys.argv[8], "spiderx": sys.argv[9],
               "vless_enc_private_key": sys.argv[10],
               "vless_enc_public_key": sys.argv[11],
               "short_ids": [s for s in sys.argv[12].split(",") if s],
               "max_time_diff": int(sys.argv[13]),
               "min_client_ver": sys.argv[14],
               "max_client_ver": sys.argv[15]}, f, indent=2)
PYEOF
    log "Reality 密钥已保存 ($WORKDIR/direct/reality.json, dest=$REALITY_DEST)"
  fi
fi
# Stale configs from a previous deploy (e.g. a core disabled since then)
# must not survive: container startup and the health check key off
# the config files' existence.
rm -f "$WORKDIR/xray/config.json" "$WORKDIR/singbox/config.json"
# Web panel files: when install.sh is run via bash <(curl ...),
# REPO_DIR is /dev/fd, so cp from the repo never works and Docker
# then auto-creates $WORKDIR/web/nginx.conf as a DIRECTORY, which
# breaks every later web-panel start with "not a directory: Are
# you trying to mount a directory onto a file". Fix 2026-11-18:
# remove a stray directory at either path first, then copy from
# the repo if present, else download from GitHub raw.
RAW_BASE="${RAW_BASE:-https://raw.githubusercontent.com/Sid-x2026/Nexus-Argo/main}"
for _f in index.html nginx.conf sub-server.py sub-generator.html; do
  [ -d "$WORKDIR/web/$_f" ] && rm -rf "$WORKDIR/web/$_f"
  if ! cp "$REPO_DIR/web/$_f" "$WORKDIR/web/$_f" 2>/dev/null; then
    curl -fsSL "$RAW_BASE/web/$_f" -o "$WORKDIR/web/$_f" 2>/dev/null || log "WARNING: could not fetch web/$_f — panel may not start"
  fi
done

step "步骤 2/5  渲染配置"
# ---- render configs with Python (never sed on JSON) ----
export NODE_UUID XRAY_PORT XRAY_DOMAIN XRAY_CONFIGS SINGBOX_PORT SINGBOX_DOMAIN SINGBOX_CONFIGS
export ENABLE_XRAY ENABLE_SINGBOX WORKDIR NODE_PREFIX NODE_PREFIX_ARGO NODE_PREFIX_DIRECT OPT_ADDRS
export ENABLE_DIRECT DIRECT_DOMAIN DIRECT_ADDRESS DIRECT_SNI DIRECT_XRAY_TLS DIRECT_XRAY_TLS_PORT
export DIRECT_SB_TLS DIRECT_SB_TLS_PORT
export DIRECT_VLESS_TCP DIRECT_VLESS_TCP_PORT DIRECT_VLESS_REALITY DIRECT_VLESS_REALITY_PORT
export DIRECT_VLESS_WS DIRECT_VLESS_WS_PORT DIRECT_VLESS_GRPC DIRECT_VLESS_GRPC_PORT
export DIRECT_TROJAN DIRECT_TROJAN_PORT DIRECT_VMESS_WS DIRECT_VMESS_WS_PORT
export DIRECT_SB_TROJAN DIRECT_SB_TROJAN_PORT DIRECT_SS DIRECT_SS_PORT
export DIRECT_HY2 DIRECT_HY2_PORT CERT_MODE
export REALITY_DEST REALITY_SNI REALITY_EFF_SNI REALITY_PRIVATE_KEY REALITY_PUBLIC_KEY REALITY_SHORT_ID
export REALITY_SHORT_IDS REALITY_MAX_TIME_DIFF REALITY_MIN_CLIENT_VER REALITY_MAX_CLIENT_VER
export REALITY_FINGERPRINT REALITY_FLOW REALITY_ENCRYPTION REALITY_SPIDERX REALITY_ENC_SERVER REALITY_ENC_CLIENT
python3 - <<'PYEOF'
import json, os, sys
work = os.environ["WORKDIR"]
uuid = os.environ["NODE_UUID"]

def parse_configs(s):
    out = []
    for item in s.split(","):
        item = item.strip()
        if not item:
            continue
        proto, _, port = item.partition(":")
        out.append({"proto": proto.strip(), "port": int(port.strip() or 443)})
    return out

def _is_true(v):
    return str(v or "").lower() in ("true", "1", "yes")


def _direct_tls():
    return {"certificates": [{"certificateFile": "/etc/nexus-direct/cert.pem",
                              "keyFile": "/etc/nexus-direct/key.pem"}]}


def render_xray(port, configs):
    # Inbounds: one unified VLESS/XHTTP tunnel inbound (if any tunnel
    # protocol is selected) + direct inbounds (if direct is on).
    # Returns None when there is nothing to listen on.
    inbounds = []
    if configs:
        # ALPN is the union of the selected protocols — this is what
        # the frontend's path=/ links imply. Mode is always "auto"
        # behind a Cloudflare Tunnel: the edge terminates TLS (h1/h2
        # TCP, h3 QUIC) and cloudflared forwards to this origin as
        # plain HTTP/1.1, so "packet-up" never reaches the origin —
        # with mode="packet-up" the inbound waits for packet-style
        # upload and every client times out (VPS test 2026-11-18:
        # tunnel healthy, Xray listening on 8222, all 15 Xray nodes
        # latency -1). "auto" lets Xray detect the forwarded stream.
        # Client links keep their per-protocol mode (h3 still says
        # packet-up to the edge); only the origin side changes.
        alpns = set()
        for c in configs:
            if c["proto"] == "xhttp_h1":
                alpns.add("http/1.1")
            elif c["proto"] == "xhttp_h2":
                alpns.add("h2")
            elif c["proto"] == "xhttp_h3":
                alpns.add("h3")
            else:
                alpns.add("h2")
        inbounds.append({
            "port": port, "protocol": "vless",
            "settings": {"clients": [{"id": uuid}], "decryption": "none"},
            "streamSettings": {
                "network": "xhttp", "security": "none",
                "xhttpSettings": {"path": "/", "mode": "auto", "alpn": sorted(alpns)}
            }
        })
    if _is_true(os.environ.get("ENABLE_DIRECT")):
        _dd = os.environ.get("DIRECT_DOMAIN", "").strip()
        if _is_true(os.environ.get("DIRECT_VLESS_TCP")):
            inbounds.append({
                "port": int(os.environ.get("DIRECT_VLESS_TCP_PORT", "8082")), "protocol": "vless",
                "settings": {"clients": [{"id": uuid}], "decryption": "none"},
                "streamSettings": {"network": "tcp", "security": "none"}
            })
        if _is_true(os.environ.get("DIRECT_XRAY_TLS")):
            inbounds.append({
                "port": int(os.environ.get("DIRECT_XRAY_TLS_PORT", "443")), "protocol": "vless",
                "settings": {"clients": [{"id": uuid}], "decryption": "none"},
                "streamSettings": {"network": "tcp", "security": "tls",
                                   "tlsSettings": _direct_tls()}
            })
        if _is_true(os.environ.get("DIRECT_VLESS_REALITY")):
            _dest = os.environ.get("REALITY_DEST", "").strip().split(":")[0]
            _sni = os.environ.get("REALITY_EFF_SNI", "").strip().split(":")[0] or _dest
            # flow 写进 client (与链接里的 flow 参数一致); VLESS
            # 加密层写进 decryption ("none" = 不开加密层, 见文件头
            # REALITY_ENCRYPTION 说明)。
            _flow = os.environ.get("REALITY_FLOW", "").strip()
            _client = {"id": uuid}
            if _flow and _flow.lower() != "none":
                _client["flow"] = _flow
            _dec = os.environ.get("REALITY_ENC_SERVER", "").strip() or "none"
            # Short IDs: 列表 (环境变量逗号分隔, 第一项即旧 REALITY_SHORT_ID);
            # maxTimeDiff / 客户端版本是 3X-UI 式 Reality 字段, x.y.z
            # 表示不限上限, 不写入配置。
            _sids = [s.strip() for s in os.environ.get("REALITY_SHORT_IDS", "").split(",") if s.strip()]
            if not _sids:
                _sids = [os.environ.get("REALITY_SHORT_ID", "")]
            _rs = {"show": False, "dest": f"{_dest}:443", "xver": 0,
                   "serverNames": [_sni],
                   "privateKey": os.environ.get("REALITY_PRIVATE_KEY", ""),
                   "shortIds": _sids,
                   "maxTimeDiff": int(os.environ.get("REALITY_MAX_TIME_DIFF", "0") or 0)}
            _min_ver = os.environ.get("REALITY_MIN_CLIENT_VER", "").strip()
            _max_ver = os.environ.get("REALITY_MAX_CLIENT_VER", "").strip()
            import re as _re
            if _re.fullmatch(r"\d+\.\d+\.\d+", _min_ver or ""):
                _rs["minClientVer"] = _min_ver
            if _re.fullmatch(r"\d+\.\d+\.\d+", _max_ver or ""):
                _rs["maxClientVer"] = _max_ver
            inbounds.append({
                "port": int(os.environ.get("DIRECT_VLESS_REALITY_PORT", "9447")), "protocol": "vless",
                "settings": {"clients": [_client], "decryption": _dec},
                "streamSettings": {"network": "tcp", "security": "reality",
                                   "realitySettings": _rs}
            })
        if _is_true(os.environ.get("DIRECT_VLESS_WS")):
            inbounds.append({
                "port": int(os.environ.get("DIRECT_VLESS_WS_PORT", "8083")), "protocol": "vless",
                "settings": {"clients": [{"id": uuid}], "decryption": "none"},
                "streamSettings": {"network": "ws", "security": "none",
                                   "wsSettings": {"path": os.environ.get("DIRECT_WS_PATH", "/ws")}}
            })
        if _is_true(os.environ.get("DIRECT_VLESS_GRPC")):
            inbounds.append({
                "port": int(os.environ.get("DIRECT_VLESS_GRPC_PORT", "8084")), "protocol": "vless",
                "settings": {"clients": [{"id": uuid}], "decryption": "none"},
                "streamSettings": {"network": "grpc", "security": "tls",
                                   "tlsSettings": _direct_tls(),
                                   "grpcSettings": {"serviceName": os.environ.get("DIRECT_GRPC_SERVICE", "grpc")}}
            })
        if _is_true(os.environ.get("DIRECT_TROJAN")):
            inbounds.append({
                "port": int(os.environ.get("DIRECT_TROJAN_PORT", "9443")), "protocol": "trojan",
                "settings": {"clients": [{"password": uuid}]},
                "streamSettings": {"network": "tcp", "security": "tls",
                                   "tlsSettings": _direct_tls()}
            })
        if _is_true(os.environ.get("DIRECT_VMESS_WS")):
            inbounds.append({
                "port": int(os.environ.get("DIRECT_VMESS_WS_PORT", "9444")), "protocol": "vmess",
                "settings": {"clients": [{"id": uuid, "alterId": 0}]},
                "streamSettings": {"network": "ws", "security": "tls",
                                   "tlsSettings": _direct_tls(),
                                   "wsSettings": {"path": os.environ.get("DIRECT_WS_PATH", "/ws")}}
            })
    if not inbounds:
        return None
    return {
        "log": {"loglevel": "warning"},
        "inbounds": inbounds,
        "outbounds": [{"protocol": "freedom", "tag": "direct"}]
    }

def render_singbox(port, configs):
    # Dispatcher design (see DISPATCHER_DESIGN.md): one VLESS inbound
    # per selected transport, each on 127.0.0.1 only, on internal ports
    # port+1 (ws, path /ws), port+2 (httpupgrade, path /httpupgrade),
    # port+3 (grpc, service_name grpc, path /grpc). A single inbound
    # can only have one transport, so this — plus the nginx dispatcher
    # in front listening on `port` — is what makes all three work on
    # one unified origin port. ws and httpupgrade send the same Upgrade
    # request headers, so they can only be told apart by path.
    # Plus a direct VLESS+TLS inbound (public port) when direct is on.
    # Returns None when there is nothing to listen on.
    protos = [c["proto"] for c in configs]
    inbounds = []
    spec = {
        "ws": (port + 1, {"type": "ws", "path": "/ws"}),
        "httpupgrade": (port + 2, {"type": "httpupgrade", "path": "/httpupgrade"}),
        "grpc": (port + 3, {"type": "grpc", "service_name": "grpc"}),
    }
    for proto in ("ws", "httpupgrade", "grpc"):
        if proto not in protos:
            continue
        iport, transport = spec[proto]
        inbounds.append({
            "type": "vless", "listen": "127.0.0.1", "listen_port": iport,
            "users": [{"uuid": uuid}],
            "transport": transport
        })
    if _is_true(os.environ.get("ENABLE_DIRECT")):
        if _is_true(os.environ.get("DIRECT_SB_TLS")):
            inbounds.append({
                "type": "vless", "listen": "0.0.0.0",
                "listen_port": int(os.environ.get("DIRECT_SB_TLS_PORT", "8443")),
                "users": [{"uuid": uuid}],
                "tls": {"enabled": True,
                        "certificate_path": "/etc/nexus-direct/cert.pem",
                        "key_path": "/etc/nexus-direct/key.pem"}
            })
        if _is_true(os.environ.get("DIRECT_SB_TROJAN")):
            inbounds.append({
                "type": "trojan", "listen": "0.0.0.0",
                "listen_port": int(os.environ.get("DIRECT_SB_TROJAN_PORT", "9445")),
                "users": [{"password": uuid}],
                "tls": {"enabled": True,
                        "certificate_path": "/etc/nexus-direct/cert.pem",
                        "key_path": "/etc/nexus-direct/key.pem"}
            })
        if _is_true(os.environ.get("DIRECT_SS")):
            inbounds.append({
                "type": "shadowsocks", "listen": "0.0.0.0",
                "listen_port": int(os.environ.get("DIRECT_SS_PORT", "8388")),
                "method": "aes-256-gcm",
                "password": uuid
            })
        if _is_true(os.environ.get("DIRECT_HY2")):
            inbounds.append({
                "type": "hysteria2", "listen": "0.0.0.0",
                "listen_port": int(os.environ.get("DIRECT_HY2_PORT", "9446")),
                "users": [{"password": uuid}],
                "tls": {"enabled": True,
                        "certificate_path": "/etc/nexus-direct/cert.pem",
                        "key_path": "/etc/nexus-direct/key.pem",
                        "alpn": ["h3"]}
            })
    if not inbounds:
        return None
    return {
        "log": {"level": "warn"},
        "inbounds": inbounds,
        "outbounds": [{"type": "direct", "tag": "direct"}]
    }

# A core is rendered when it has a tunnel inbound, a direct inbound,
# or both; a core with nothing to listen on gets no config file at all
# (container startup and the health check key off the file's existence).
xray_cfg = render_xray(int(os.environ["XRAY_PORT"]), parse_configs(os.environ["XRAY_CONFIGS"]) if _is_true(os.environ.get("ENABLE_XRAY")) else [])
if xray_cfg is not None:
    with open(f"{work}/xray/config.json", "w") as f:
        json.dump(xray_cfg, f, indent=2)
sb_cfg = render_singbox(int(os.environ["SINGBOX_PORT"]), parse_configs(os.environ["SINGBOX_CONFIGS"]) if _is_true(os.environ.get("ENABLE_SINGBOX")) else [])
if sb_cfg is not None:
    with open(f"{work}/singbox/config.json", "w") as f:
        json.dump(sb_cfg, f, indent=2)

# Subscription files served by the panel nginx at /sub/merged/<uuid>
# and /sub/raw/<uuid> (static, deploy-time fission). The public
# sub-domain service (web/sub-server.py, v3.2) generates the same
# links live from these variables, so ?addrs= works there too.
# NOTE: the frontend now passes OPT_ADDRS in the SSH command (2026-11-18),
# so the server reproduces the same fission as the frontend — verified
# 2026-11-18: frontend nodes == sub/merged.txt, 18/18 identical.
# Native = 1 protocol = 1 node, address = tunnel domain.
# Dynamic = native x preferred addresses, address = preferred addr, sni = domain.
# OPT_ADDRS is comma-separated; default cloudflare.com (frontend default).
# Node prefixes, split (Part A/B contract): tunnel links use the
# Argo prefix, direct links use the Direct prefix. Old single
# NODE_PREFIX is the fallback for both when the new vars are empty.
_np = os.environ.get("NODE_PREFIX", "") or ""
prefix_argo = os.environ.get("NODE_PREFIX_ARGO", "") or _np or "Argo"
prefix_direct = os.environ.get("NODE_PREFIX_DIRECT", "") or _np or "直连"
opt_addrs = [a.strip() for a in os.environ.get("OPT_ADDRS", "cloudflare.com").split(",") if a.strip()] or ["cloudflare.com"]
with open(f"{work}/sub/opt_addrs.txt", "w") as f:
    f.write("\n".join(opt_addrs) + "\n")

def vless_link(addr, domain, proto, port, core):
    if core == "xray":
        alpn = {"xhttp_h1": "http/1.1", "xhttp_h2": "h2", "xhttp_h3": "h3"}.get(proto, "h2")
        mode = "packet-up" if proto == "xhttp_h3" else "auto"
        return (f"vless://{uuid}@{addr}:{port}/?encryption=none&security=tls"
                f"&sni={domain}&type=xhttp&mode={mode}&path=%2F&alpn={alpn}"
                f"#{prefix_argo}丨Xray丨{proto}")
    # Sing-box paths must match the dispatcher (see DISPATCHER_DESIGN.md):
    # ws /ws, httpupgrade /httpupgrade, grpc serviceName=grpc.
    if proto == "grpc":
        svc = "&serviceName=grpc"
    elif proto == "httpupgrade":
        svc = "&path=%2Fhttpupgrade"
    else:
        svc = "&path=%2Fws"
    # ALPN per protocol (VPS test 2026-11-18): ws/httpupgrade are
    # HTTP/1.1 Upgrade only, grpc is h2 only. Offering h2 first
    # breaks ws/httpupgrade (client negotiates h2).
    alpn = "h2" if proto == "grpc" else "http/1.1"
    return (f"vless://{uuid}@{addr}:{port}/?encryption=none&security=tls"
            f"&sni={domain}&type={proto}{svc}&alpn={alpn}"
            f"#{prefix_argo}丨Singbox丨{proto}")

tunnel_native = []
if _is_true(os.environ.get("ENABLE_XRAY")):
    for c in parse_configs(os.environ["XRAY_CONFIGS"]):
        tunnel_native.append(vless_link(os.environ["XRAY_DOMAIN"], os.environ["XRAY_DOMAIN"], c["proto"], c["port"], "xray"))
if _is_true(os.environ.get("ENABLE_SINGBOX")):
    for c in parse_configs(os.environ["SINGBOX_CONFIGS"]):
        tunnel_native.append(vless_link(os.environ["SINGBOX_DOMAIN"], os.environ["SINGBOX_DOMAIN"], c["proto"], c["port"], "sb"))
# Direct nodes enter the subscription as-is — never fissioned
# (their address is the VPS itself). TLS direct links carry
# allowInsecure=1 unless CERT_MODE=acme (valid cert); plain-TCP /
# plain-WS links carry none; direct is a backup, not the main path.
# Remark format: "<direct-prefix>丨<Name>" (e.g. 直连丨Xray-TLS) —
# the Direct prefix already says 直连, so there is no middle 直连
# segment. Keep in sync with web/sub-server.py direct_links() —
# same names, same link shapes.
import base64 as _b64link
import urllib.parse as _uparse

def _ai():
    # allowInsecure suffix for TLS direct links ("" for a valid ACME cert).
    return "" if os.environ.get("CERT_MODE", "selfsigned") == "acme" else "&allowInsecure=1"

def _vmess_link(dd, port):
    cfg = {"v": "2", "ps": f"{prefix_direct}丨Xray-VMess-WS", "add": dd, "port": str(port),
           "id": uuid, "aid": "0", "net": "ws", "type": "none", "host": dd,
           "path": os.environ.get("DIRECT_WS_PATH", "/ws"), "tls": "tls", "sni": dd}
    return "vmess://" + _b64link.b64encode(json.dumps(cfg, ensure_ascii=False).encode()).decode()

def _ss_link(dd, port):
    raw = f"aes-256-gcm:{uuid}@{dd}:{port}".encode()
    return ("ss://" + _b64link.urlsafe_b64encode(raw).decode().rstrip("=")
            + f"#{prefix_direct}丨Singbox-SS")

direct = []
if _is_true(os.environ.get("ENABLE_DIRECT")):
    _dd = os.environ.get("DIRECT_DOMAIN", "").strip()
    _dsni = os.environ.get("DIRECT_SNI", "").strip() or _dd
    if _dd:
        if _is_true(os.environ.get("DIRECT_XRAY_TLS")):
            direct.append(f"vless://{uuid}@{_dd}:{os.environ.get('DIRECT_XRAY_TLS_PORT', '443')}/?encryption=none&security=tls&sni={_dsni}&type=tcp{_ai()}#{prefix_direct}丨Xray-TLS")
        if _is_true(os.environ.get("DIRECT_VLESS_TCP")):
            direct.append(f"vless://{uuid}@{_dd}:{os.environ.get('DIRECT_VLESS_TCP_PORT', '8082')}/?encryption=none&type=tcp#{prefix_direct}丨Xray-TCP")
        if _is_true(os.environ.get("DIRECT_VLESS_REALITY")):
            _rdest = os.environ.get("REALITY_DEST", "").strip().split(":")[0]
            _rsni = os.environ.get("REALITY_EFF_SNI", "").strip().split(":")[0] or _rdest
            # Reality 链接: 地址 = 直连域名 (或 VPS IP), SNI = 大厂域名
            # (reality_dest, 或 reality_sni); 带指纹 / flow / 加密层 /
            # spiderX (spiderX 只在不是默认值 "/" 时才带)。
            _rfp = os.environ.get("REALITY_FINGERPRINT", "").strip() or "chrome"
            _rflow = os.environ.get("REALITY_FLOW", "").strip()
            _renc = os.environ.get("REALITY_ENC_CLIENT", "").strip() or "none"
            _rspx = os.environ.get("REALITY_SPIDERX", "").strip() or "/"
            _rlink = (f"vless://{uuid}@{_dd}:{os.environ.get('DIRECT_VLESS_REALITY_PORT', '9447')}/"
                      f"?encryption={_renc}&security=reality"
                      f"&pbk={os.environ.get('REALITY_PUBLIC_KEY', '')}"
                      f"&sid={os.environ.get('REALITY_SHORT_ID', '')}&sni={_rsni}&fp={_rfp}")
            if _rflow and _rflow.lower() != "none":
                _rlink += f"&flow={_rflow}"
            _rlink += "&type=tcp"
            if _rspx != "/":
                _rlink += "&spiderX=" + _uparse.quote(_rspx, safe="/")
            _rlink += f"#{prefix_direct}丨Xray-Reality"
            direct.append(_rlink)
        if _is_true(os.environ.get("DIRECT_VLESS_WS")):
            direct.append(f"vless://{uuid}@{_dd}:{os.environ.get('DIRECT_VLESS_WS_PORT', '8083')}/?encryption=none&type=ws&path={_uparse.quote(os.environ.get('DIRECT_WS_PATH', '/ws'), safe='')}#{prefix_direct}丨Xray-WS")
        if _is_true(os.environ.get("DIRECT_VLESS_GRPC")):
            direct.append(f"vless://{uuid}@{_dd}:{os.environ.get('DIRECT_VLESS_GRPC_PORT', '8084')}/?encryption=none&security=tls&sni={_dsni}&type=grpc&serviceName={_uparse.quote(os.environ.get('DIRECT_GRPC_SERVICE', 'grpc'), safe='')}{_ai()}#{prefix_direct}丨Xray-gRPC")
        if _is_true(os.environ.get("DIRECT_TROJAN")):
            direct.append(f"trojan://{uuid}@{_dd}:{os.environ.get('DIRECT_TROJAN_PORT', '9443')}?security=tls&sni={_dsni}{_ai()}#{prefix_direct}丨Xray-Trojan")
        if _is_true(os.environ.get("DIRECT_VMESS_WS")):
            direct.append(_vmess_link(_dd, os.environ.get("DIRECT_VMESS_WS_PORT", "9444")))
        if _is_true(os.environ.get("DIRECT_SB_TLS")):
            direct.append(f"vless://{uuid}@{_dd}:{os.environ.get('DIRECT_SB_TLS_PORT', '8443')}/?encryption=none&security=tls&sni={_dsni}&type=tcp{_ai()}#{prefix_direct}丨Singbox-TLS")
        if _is_true(os.environ.get("DIRECT_SB_TROJAN")):
            direct.append(f"trojan://{uuid}@{_dd}:{os.environ.get('DIRECT_SB_TROJAN_PORT', '9445')}?security=tls&sni={_dsni}{_ai()}#{prefix_direct}丨Singbox-Trojan")
        if _is_true(os.environ.get("DIRECT_SS")):
            direct.append(_ss_link(_dd, os.environ.get("DIRECT_SS_PORT", "8388")))
        if _is_true(os.environ.get("DIRECT_HY2")):
            direct.append(f"hysteria2://{uuid}@{_dd}:{os.environ.get('DIRECT_HY2_PORT', '9446')}?insecure=1&sni={_dsni}#{prefix_direct}丨Singbox-Hysteria2")
native = tunnel_native + direct
# merged: re-derive with preferred addr as address, keeping domain as sni.
# Rebuild from configs (not by string-replacing native links) so sni stays correct.
merged = []
if _is_true(os.environ.get("ENABLE_XRAY")):
    for c in parse_configs(os.environ["XRAY_CONFIGS"]):
        for addr in opt_addrs:
            merged.append(vless_link(addr, os.environ["XRAY_DOMAIN"], c["proto"], c["port"], "xray"))
if _is_true(os.environ.get("ENABLE_SINGBOX")):
    for c in parse_configs(os.environ["SINGBOX_CONFIGS"]):
        for addr in opt_addrs:
            merged.append(vless_link(addr, os.environ["SINGBOX_DOMAIN"], c["proto"], c["port"], "sb"))
merged = merged + direct
with open(f"{work}/sub/raw.txt", "w") as f:
    f.write("\n".join(native) + ("\n" if native else ""))
with open(f"{work}/sub/merged.txt", "w") as f:
    f.write("\n".join(merged) + ("\n" if merged else ""))
# base64 versions — what the subscription endpoints serve (same format
# the Worker used to return, so clients need no change). v3 2026-11-19.
import base64 as _b64
with open(f"{work}/sub/raw.b64", "w") as f:
    f.write(_b64.b64encode(("\n".join(native) + ("\n" if native else "")).encode()).decode())
with open(f"{work}/sub/merged.b64", "w") as f:
    f.write(_b64.b64encode(("\n".join(merged) + ("\n" if merged else "")).encode()).decode())
print(f"rendered {len(native)} native links, {len(merged)} dynamic links ({len(native)} x {len(opt_addrs)} preferred)")
PYEOF

# ---- tunnel routing: Dashboard-managed token tunnel ----
# A token tunnel's ingress is configured in Cloudflare Zero Trust
# (Networks > Tunnels > <tunnel> > Public Hostnames), NOT in a local
# config.yml. Create two hostnames sharing this one token:
#   <XRAY_DOMAIN>   -> http://127.0.0.1:<XRAY_PORT>
#   <SINGBOX_DOMAIN> -> http://127.0.0.1:<SINGBOX_PORT>
#   <SUB_DOMAIN>     -> http://127.0.0.1:<SUB_PORT>   (v3: subscription only,
#     serves just /sub/* — no panel, no deploy command, nothing else)
# (Only the hostnames for enabled cores, plus the subscription one.)
# (Only the hostnames for enabled cores.) No config.yml is written
# on purpose — a local one would be ignored by `run --token`.
if [ -n "$ARGO_TOKEN" ] || is_true "$ENABLE_DIRECT"; then
  cat > "$WORKDIR/ROUTES.md" <<EOF
# Routes — create the tunnel ones in Cloudflare Zero Trust
# Tunnel token: <the ARGO_TOKEN you supplied; do not commit this file>
EOF
  if [ -n "$ARGO_TOKEN" ]; then
    if is_true "$ENABLE_XRAY"; then
      printf -- '- %s -> http://127.0.0.1:%s\n' "$XRAY_DOMAIN" "$XRAY_PORT" >> "$WORKDIR/ROUTES.md"
    fi
    if is_true "$ENABLE_SINGBOX"; then
      printf -- '- %s -> http://127.0.0.1:%s\n' "$SINGBOX_DOMAIN" "$SINGBOX_PORT" >> "$WORKDIR/ROUTES.md"
    fi
    if [ -n "$SUB_DOMAIN" ]; then
      printf -- '- %s -> http://127.0.0.1:%s  (subscription only)\n' "$SUB_DOMAIN" "$SUB_PORT" >> "$WORKDIR/ROUTES.md"
    fi
    log "Create the routes in $WORKDIR/ROUTES.md in Zero Trust before testing the tunnel."
  fi
  if is_true "$ENABLE_DIRECT"; then
    {
      echo ""
      echo "# Direct nodes — no tunnel, connect straight to the VPS (backup only, exposes the real IP)"
      echo "# Self-signed cert: clients need allowInsecure=1"
    } >> "$WORKDIR/ROUTES.md"
    if is_true "$DIRECT_XRAY_TLS"; then
      printf -- '- Xray VLESS+TLS: %s:%s\n' "$DIRECT_DOMAIN" "$DIRECT_XRAY_TLS_PORT" >> "$WORKDIR/ROUTES.md"
    fi
    if is_true "$DIRECT_VLESS_TCP"; then
      printf -- '- Xray VLESS+TCP (plain, no TLS): %s:%s\n' "$DIRECT_DOMAIN" "$DIRECT_VLESS_TCP_PORT" >> "$WORKDIR/ROUTES.md"
    fi
    if is_true "$DIRECT_VLESS_REALITY"; then
      printf -- '- Xray VLESS+Reality (dest %s): %s:%s\n' "$REALITY_DEST" "$DIRECT_DOMAIN" "$DIRECT_VLESS_REALITY_PORT" >> "$WORKDIR/ROUTES.md"
    fi
    if is_true "$DIRECT_VLESS_WS"; then
      printf -- '- Xray VLESS+WS (plain, path /ws): %s:%s\n' "$DIRECT_DOMAIN" "$DIRECT_VLESS_WS_PORT" >> "$WORKDIR/ROUTES.md"
    fi
    if is_true "$DIRECT_VLESS_GRPC"; then
      printf -- '- Xray VLESS+gRPC+TLS (serviceName grpc): %s:%s\n' "$DIRECT_DOMAIN" "$DIRECT_VLESS_GRPC_PORT" >> "$WORKDIR/ROUTES.md"
    fi
    if is_true "$DIRECT_TROJAN"; then
      printf -- '- Xray Trojan+TLS: %s:%s\n' "$DIRECT_DOMAIN" "$DIRECT_TROJAN_PORT" >> "$WORKDIR/ROUTES.md"
    fi
    if is_true "$DIRECT_VMESS_WS"; then
      printf -- '- Xray VMess+WS+TLS (path /ws): %s:%s\n' "$DIRECT_DOMAIN" "$DIRECT_VMESS_WS_PORT" >> "$WORKDIR/ROUTES.md"
    fi
    if is_true "$DIRECT_SB_TLS"; then
      printf -- '- Sing-box VLESS+TLS: %s:%s\n' "$DIRECT_DOMAIN" "$DIRECT_SB_TLS_PORT" >> "$WORKDIR/ROUTES.md"
    fi
    if is_true "$DIRECT_SB_TROJAN"; then
      printf -- '- Sing-box Trojan+TLS: %s:%s\n' "$DIRECT_DOMAIN" "$DIRECT_SB_TROJAN_PORT" >> "$WORKDIR/ROUTES.md"
    fi
    if is_true "$DIRECT_SS"; then
      printf -- '- Sing-box Shadowsocks (aes-256-gcm): %s:%s\n' "$DIRECT_DOMAIN" "$DIRECT_SS_PORT" >> "$WORKDIR/ROUTES.md"
    fi
    if is_true "$DIRECT_HY2"; then
      printf -- '- Sing-box Hysteria2 (UDP, alpn h3): %s:%s\n' "$DIRECT_DOMAIN" "$DIRECT_HY2_PORT" >> "$WORKDIR/ROUTES.md"
    fi
  fi
fi

# ---- Sing-box dispatcher: nginx on the unified origin port ----
# Listens on SINGBOX_PORT, routes by path to the three 127.0.0.1
# inbounds (port+1 ws, port+2 httpupgrade, port+3 grpc). The tunnel
# route still points at SINGBOX_PORT — now at the dispatcher, not
# directly at sing-box. nginx does no ws framing after a 101, it
# just pipes bytes, so httpupgrade survives it; grpc uses grpc_pass.
# Only locations for selected protocols are written; others 404.
if is_true "$ENABLE_SINGBOX"; then
  mkdir -p "$WORKDIR/sb-dispatch"
  _sb_ws=$(( SINGBOX_PORT + 1 )); _sb_hu=$(( SINGBOX_PORT + 2 )); _sb_gr=$(( SINGBOX_PORT + 3 ))
  {
    echo "server {"
    echo "    listen $SINGBOX_PORT;"
    echo "    server_name _;"
    case ",$SINGBOX_CONFIGS," in
      *,ws:*) echo "    location /ws {"; echo "        proxy_pass http://127.0.0.1:$_sb_ws;"; echo "        proxy_http_version 1.1;"; echo "        proxy_set_header Upgrade \$http_upgrade;"; echo "        proxy_set_header Connection \"upgrade\";"; echo "        proxy_set_header Host \$host;"; echo "        proxy_read_timeout 86400;"; echo "    }";;
    esac
    case ",$SINGBOX_CONFIGS," in
      *,httpupgrade:*) echo "    location /httpupgrade {"; echo "        proxy_pass http://127.0.0.1:$_sb_hu;"; echo "        proxy_http_version 1.1;"; echo "        proxy_set_header Upgrade \$http_upgrade;"; echo "        proxy_set_header Connection \"upgrade\";"; echo "        proxy_set_header Host \$host;"; echo "        proxy_read_timeout 86400;"; echo "    }";;
    esac
    case ",$SINGBOX_CONFIGS," in
      *,grpc:*) echo "    location /grpc {"; echo "        grpc_pass grpc://127.0.0.1:$_sb_gr;"; echo "        grpc_read_timeout 86400;"; echo "        grpc_send_timeout 86400;"; echo "    }";;
    esac
    echo "    location / { return 404; }"
    echo "}"
  } > "$WORKDIR/sb-dispatch/nginx.conf"
  log "Sing-box dispatcher config written ($WORKDIR/sb-dispatch/nginx.conf)"
fi

step "步骤 3/5  启动容器"
# ---- (re)start containers — host network so 127.0.0.1 origins work ----
docker rm -f nexus-xray nexus-singbox nexus-sb-dispatch nexus-argo nexus-web-panel nexus-sub >/dev/null 2>&1 || true

# A core container starts when its config file was rendered (tunnel
# inbound, direct inbound, or both); a core with nothing to listen
# on gets no container. The dispatcher only serves the tunnel
# Sing-box origin port, so it only runs when tunnel Sing-box is on.
if [ -f "$WORKDIR/xray/config.json" ]; then
  _xray_vol=(-v "$WORKDIR/xray/config.json:/etc/xray/config.json:ro")
  if is_true "$ENABLE_DIRECT" && [ -d "$WORKDIR/direct" ]; then
    _xray_vol+=(-v "$WORKDIR/direct:/etc/nexus-direct:ro")
  fi
  docker run -d --name nexus-xray --restart unless-stopped --network host \
    "${_xray_vol[@]}" \
    "$XRAY_IMAGE" run -c /etc/xray/config.json
fi
if [ -f "$WORKDIR/singbox/config.json" ]; then
  _sb_vol=(-v "$WORKDIR/singbox/config.json:/etc/sing-box/config.json:ro")
  if is_true "$ENABLE_DIRECT" && [ -d "$WORKDIR/direct" ]; then
    _sb_vol+=(-v "$WORKDIR/direct:/etc/nexus-direct:ro")
  fi
  docker run -d --name nexus-singbox --restart unless-stopped --network host \
    "${_sb_vol[@]}" \
    "$SINGBOX_IMAGE" -c /etc/sing-box/config.json run
fi
if is_true "$ENABLE_SINGBOX"; then
  docker run -d --name nexus-sb-dispatch --restart unless-stopped --network host \
    -v "$WORKDIR/sb-dispatch/nginx.conf:/etc/nginx/conf.d/default.conf:ro" \
    "$NGINX_IMAGE"
fi
if [ -n "$ARGO_TOKEN" ]; then
  docker run -d --name nexus-argo --restart unless-stopped --network host \
    "$CLOUDFLARED_IMAGE" tunnel --no-autoupdate --protocol "$TUNNEL_PROTOCOL" run --token "$ARGO_TOKEN"
fi
if [ -f "$WORKDIR/web/nginx.conf" ] && [ -f "$WORKDIR/web/index.html" ]; then
  # Panel is bound to 127.0.0.1 only (2026-11-18): it has no login,
  # so it must never be exposed on the VPS public IP:8080, and no
  # tunnel route should point at it. Access it via SSH port-forward
  # (ssh -L 8080:127.0.0.1:8080 root@<VPS-IP>) or via Cloudflare Access.
  docker run -d --name nexus-web-panel --restart unless-stopped \
    -p 127.0.0.1:8080:80 \
    -v "$WORKDIR/web/index.html:/usr/share/nginx/html/index.html:ro" \
    -v "$WORKDIR/web/nginx.conf:/etc/nginx/conf.d/default.conf:ro" \
    -v "$WORKDIR/sub:/usr/share/nginx/html/sub:ro" \
    "$NGINX_IMAGE"
else
  log "WARNING: web panel files missing — skipping nexus-web-panel, nodes are unaffected"
fi
if [ -n "$SUB_DOMAIN" ]; then
  # v3.2 subscription-only service: a tiny Python stdlib server
  # (web/sub-server.py) that generates subscriptions on the fly
  # from this deploy command's variables — so ?addrs= live fission
  # works again without a Worker. No static files to serve, no
  # nginx root to misconfigure (v3.1's bug class is gone by design).
  # Bound to 127.0.0.1 — public access is only via the tunnel route
  # SUB_DOMAIN -> 127.0.0.1:SUB_PORT (see ROUTES.md).
  # The server listens on SUB_PORT inside the container too.
  # 订阅生成器面板 (web/sub-generator.html): 跟着 nexus-sub 一起部署,
  # 打开 https://$SUB_DOMAIN/ 就是生成器, 上面原生订阅、中间优选域名
  # 获取+测速、下面裂变出动态订阅, 不用 Worker、不用另外部署。
  if [ -f "$WORKDIR/web/sub-server.py" ]; then
    # 生成器是可选的: 文件不存在就不挂载 (直接挂一个不存在的文件,
    # Docker 会在宿主上自动建一个同名目录, 反而把事搞坏)。
    _gen_vol=()
    if [ -f "$WORKDIR/web/sub-generator.html" ]; then
      _gen_vol=(-v "$WORKDIR/web/sub-generator.html:/app/sub-generator.html:ro")
    else
      log "WARNING: web/sub-generator.html 缺失 — 生成器面板不可用, 订阅本身不受影响"
    fi
    docker run -d --name nexus-sub --restart unless-stopped \
      -p 127.0.0.1:"$SUB_PORT":"$SUB_PORT" \
      -e NODE_UUID="$NODE_UUID" -e NODE_PREFIX="$NODE_PREFIX" \
      -e NODE_PREFIX_ARGO="$NODE_PREFIX_ARGO" -e NODE_PREFIX_DIRECT="$NODE_PREFIX_DIRECT" \
      -e XRAY_DOMAIN="$XRAY_DOMAIN" -e XRAY_CONFIGS="$XRAY_CONFIGS" \
      -e SINGBOX_DOMAIN="$SINGBOX_DOMAIN" -e SINGBOX_CONFIGS="$SINGBOX_CONFIGS" \
      -e ENABLE_XRAY="$ENABLE_XRAY" -e ENABLE_SINGBOX="$ENABLE_SINGBOX" \
      -e OPT_ADDRS="$OPT_ADDRS" -e SUB_PORT="$SUB_PORT" -e SUB_PATH="$SUB_PATH" \
      -e ENABLE_DIRECT="$ENABLE_DIRECT" -e DIRECT_DOMAIN="$DIRECT_DOMAIN" \
      -e DIRECT_XRAY_TLS="$DIRECT_XRAY_TLS" -e DIRECT_XRAY_TLS_PORT="$DIRECT_XRAY_TLS_PORT" \
      -e DIRECT_SB_TLS="$DIRECT_SB_TLS" -e DIRECT_SB_TLS_PORT="$DIRECT_SB_TLS_PORT" \
      -e DIRECT_VLESS_TCP="$DIRECT_VLESS_TCP" -e DIRECT_VLESS_TCP_PORT="$DIRECT_VLESS_TCP_PORT" \
      -e DIRECT_VLESS_REALITY="$DIRECT_VLESS_REALITY" -e DIRECT_VLESS_REALITY_PORT="$DIRECT_VLESS_REALITY_PORT" \
      -e DIRECT_VLESS_WS="$DIRECT_VLESS_WS" -e DIRECT_VLESS_WS_PORT="$DIRECT_VLESS_WS_PORT" \
      -e DIRECT_VLESS_GRPC="$DIRECT_VLESS_GRPC" -e DIRECT_VLESS_GRPC_PORT="$DIRECT_VLESS_GRPC_PORT" \
      -e DIRECT_WS_PATH="$DIRECT_WS_PATH" -e DIRECT_GRPC_SERVICE="$DIRECT_GRPC_SERVICE" \
      -e DIRECT_TROJAN="$DIRECT_TROJAN" -e DIRECT_TROJAN_PORT="$DIRECT_TROJAN_PORT" \
      -e DIRECT_VMESS_WS="$DIRECT_VMESS_WS" -e DIRECT_VMESS_WS_PORT="$DIRECT_VMESS_WS_PORT" \
      -e DIRECT_SB_TROJAN="$DIRECT_SB_TROJAN" -e DIRECT_SB_TROJAN_PORT="$DIRECT_SB_TROJAN_PORT" \
      -e DIRECT_SS="$DIRECT_SS" -e DIRECT_SS_PORT="$DIRECT_SS_PORT" \
      -e DIRECT_HY2="$DIRECT_HY2" -e DIRECT_HY2_PORT="$DIRECT_HY2_PORT" \
      -e CERT_MODE="$CERT_MODE" \
      -e REALITY_DEST="$REALITY_DEST" -e REALITY_SNI="$REALITY_SNI" \
      -e REALITY_EFF_SNI="$REALITY_EFF_SNI" -e REALITY_PUBLIC_KEY="$REALITY_PUBLIC_KEY" \
      -e REALITY_SHORT_ID="$REALITY_SHORT_ID" -e REALITY_SHORT_IDS="$REALITY_SHORT_IDS" \
      -e REALITY_MAX_TIME_DIFF="$REALITY_MAX_TIME_DIFF" -e REALITY_MIN_CLIENT_VER="$REALITY_MIN_CLIENT_VER" \
      -e REALITY_MAX_CLIENT_VER="$REALITY_MAX_CLIENT_VER" \
      -e REALITY_FINGERPRINT="$REALITY_FINGERPRINT" -e REALITY_FLOW="$REALITY_FLOW" \
      -e REALITY_ENCRYPTION="$REALITY_ENCRYPTION" -e REALITY_SPIDERX="$REALITY_SPIDERX" \
      -e REALITY_ENC_CLIENT="$REALITY_ENC_CLIENT" \
      -v "$WORKDIR/web/sub-server.py:/app/sub-server.py:ro" \
      "${_gen_vol[@]}" \
      "$PYTHON_IMAGE" python3 /app/sub-server.py
  else
    log "WARNING: web/sub-server.py missing — skipping nexus-sub, panel-local subscription still works"
  fi
else
  log "SUB_DOMAIN empty — skipping nexus-sub (subscription only via panel localhost)"
fi

step "步骤 4/5  健康检查"
# ---- health check: docker inspect .State.Running, last 20 log lines on failure ----
fail=0
for c in nexus-xray nexus-singbox nexus-sb-dispatch nexus-argo nexus-web-panel nexus-sub; do
  # skip disabled cores / missing token
  case "$c" in
    nexus-xray) [ -f "$WORKDIR/xray/config.json" ] || continue;;
    nexus-singbox) [ -f "$WORKDIR/singbox/config.json" ] || continue;;
    nexus-sb-dispatch) is_true "$ENABLE_SINGBOX" || continue;;
    nexus-argo) [ -n "$ARGO_TOKEN" ] || continue;;
    nexus-web-panel) docker inspect "$c" >/dev/null 2>&1 || continue;;
    nexus-sub) [ -n "$SUB_DOMAIN" ] && docker inspect "$c" >/dev/null 2>&1 || continue;;
  esac
  sleep 2
  running="$(docker inspect -f '{{.State.Running}}' "$c" 2>/dev/null || echo false)"
  if [ "$running" != "true" ]; then
    echo "[nexus-argo] ERROR: $c is not running — last 20 log lines:"
    docker logs --tail 20 "$c" 2>&1 || true
    fail=1
  else
    ok "$c 运行中"
  fi
done
# v3.1: a running container is not proof the subscription works — with a
# wrong/missing root, nginx starts fine and answers 404 to every
# /sub/* URL (found 2026-11-19 by live test: the nginx:alpine image's
# compiled-in default root is /etc/nginx/html, files live in
# /usr/share/nginx/html). Prove the endpoint serves real data before
# printing public links. Same check for the panel (it serves / and
# /sub/* from the same mount).
if command -v curl >/dev/null 2>&1; then
  if [ -n "$SUB_DOMAIN" ] && docker inspect nexus-sub >/dev/null 2>&1; then
    _sub_body="$(curl -fsS --max-time 10 "http://127.0.0.1:$SUB_PORT/$SUB_PATH/raw/$NODE_UUID" 2>/dev/null || true)"
    if [ -z "$_sub_body" ] || ! printf '%s' "$_sub_body" | base64 -d 2>/dev/null | grep -q '://'; then
      echo "[nexus-argo] ERROR: nexus-sub is running but /$SUB_PATH/raw/<uuid> did not return subscription data — check: docker logs nexus-sub"
      fail=1
    else
      log "nexus-sub serves /$SUB_PATH/raw/<uuid> OK"
    fi
    # v3.2: prove live fission works — ?addrs= with 2 addresses must
    # return exactly 2x the tunnel-native link count, plus the direct
    # links unchanged (direct nodes are never fissioned). A server that
    # only served static files would return the deploy-time count instead.
    if [ "$fail" = "0" ]; then
      _native_n=$(grep -c . "$WORKDIR/sub/raw.txt" 2>/dev/null || true); _native_n="${_native_n:-0}"
      # Tunnel links carry a literal 丨Xray丨 / 丨Singbox丨 remark; direct
      # links are the rest (the VMess link's remark is base64-encoded
      # inside the link, so grep '丨直连丨' would miss it — count direct
      # as native minus tunnel instead).
      _tunnel_n=$(grep -cE '丨(Xray|Singbox)丨' "$WORKDIR/sub/raw.txt" 2>/dev/null || true); _tunnel_n="${_tunnel_n:-0}"
      _direct_n=$(( _native_n - _tunnel_n ))
      _want=$(( _tunnel_n * 2 + _direct_n ))
      _merged_body="$(curl -fsS --max-time 10 "http://127.0.0.1:$SUB_PORT/$SUB_PATH/merged/$NODE_UUID?addrs=cf.xreak.top,cf.3666888.xyz" 2>/dev/null || true)"
      _merged_n=$(printf '%s' "$_merged_body" | base64 -d 2>/dev/null | grep -c '://' || true)
      if [ "$_merged_n" != "$_want" ]; then
        echo "[nexus-argo] ERROR: nexus-sub ?addrs= fission check failed — expected $_want links for 2 addrs, got ${_merged_n:-0} — check: docker logs nexus-sub"
        fail=1
      else
        log "nexus-sub ?addrs= live fission OK ($_merged_n links for 2 addrs)"
      fi
    fi
    # 生成器面板: 只有文件在时才要求 / 返回生成器; 文件缺失是
    # 可选功能未装, 只警告、不让健康检查失败 (2026-11-19 教训)。
    if [ "$fail" = "0" ]; then
      if [ ! -f "$WORKDIR/web/sub-generator.html" ]; then
        log "WARNING: sub-generator.html 缺失 — 跳过生成器面板检查, 订阅不受影响"
      elif curl -fsS --max-time 10 "http://127.0.0.1:$SUB_PORT/" 2>/dev/null | grep -q '订阅生成器'; then
        log "nexus-sub generator panel OK"
      else
        echo "[nexus-argo] ERROR: nexus-sub / did not return the generator panel — check web/sub-generator.html is present"
        fail=1
      fi
    fi
  fi
  if docker inspect nexus-web-panel >/dev/null 2>&1; then
    if ! curl -fsS --max-time 10 -o /dev/null "http://127.0.0.1:8080/" 2>/dev/null; then
      echo "[nexus-argo] ERROR: nexus-web-panel is running but / did not return 200 — check: docker logs nexus-web-panel"
      fail=1
    else
      log "nexus-web-panel serves / OK"
    fi
  fi
else
  log "WARNING: curl not found — skipping HTTP smoke check for nexus-sub / panel"
fi
[ "$fail" = "0" ] || die "health check failed — see logs above"

# ---- subscription summary: print the links so the deployer can see/copy them ----
# Native links are in $WORKDIR/sub/raw.txt (1 protocol = 1 node, address = tunnel domain).
# Dynamic links are in $WORKDIR/sub/merged.txt (native x preferred addresses).
# The panel serves them locally at /sub/raw/<uuid> and /sub/merged/<uuid>
# (panel is bound to 127.0.0.1:8080 only — access via ssh -L 8080:127.0.0.1:8080).
# v3.2: the public link is the subscription-only service — no Worker
# needed. Put this URL straight into the client; it serves base64,
# same as the Worker used to. Changing preferred addresses NO LONGER
# needs a redeploy: just edit ?addrs= in the URL — the server on the
# VPS fissions live from the same deploy-command variables.
# (v3.0's static nginx files had no ?addrs=; v3.2's Python server
# restores it. The panel's local 8080 subscription is still static
# files, so ?addrs= only works on the public sub-domain URL.)
step "步骤 5/5  订阅汇总"
_native_n=0; _merged_n=0
[ -f "$WORKDIR/sub/raw.txt" ] && _native_n=$(grep -c . "$WORKDIR/sub/raw.txt" || true)
[ -f "$WORKDIR/sub/merged.txt" ] && _merged_n=$(grep -c . "$WORKDIR/sub/merged.txt" || true)
echo ""
sep
echo "${C_GREEN}${C_BOLD}  ★ 部署完成, 请保存下面的订阅地址 ★${C_RESET}"
sep
echo "原生订阅文件: $WORKDIR/sub/raw.txt ($_native_n 条节点)"
echo "动态订阅文件: $WORKDIR/sub/merged.txt ($_merged_n 条节点)"
echo ""
echo "${C_BOLD}面板本地订阅${C_RESET} (需 SSH 端口转发 ssh -L 8080:127.0.0.1:8080, 本地路径固定是 /sub/):"
echo "  原生: http://127.0.0.1:8080/sub/raw/$NODE_UUID"
echo "  动态: http://127.0.0.1:8080/sub/merged/$NODE_UUID"
if [ -n "${SUB_DOMAIN:-}" ]; then
  echo ""
  echo "${C_BOLD}订阅生成器面板${C_RESET} (打开就是, 上面原生订阅、下面优选IP裂变):"
  echo "  ${C_GREEN}https://$SUB_DOMAIN/${C_RESET}"
  echo "${C_BOLD}订阅 (公网, 直接加到客户端, 不用 Worker):${C_RESET}"
  echo "  原生: ${C_GREEN}https://$SUB_DOMAIN/$SUB_PATH/raw/$NODE_UUID${C_RESET}"
  echo "  动态: ${C_GREEN}https://$SUB_DOMAIN/$SUB_PATH/merged/$NODE_UUID${C_RESET}"
  echo "  换优选地址不用重部署, 直接改 URL: https://$SUB_DOMAIN/$SUB_PATH/merged/$NODE_UUID?addrs=cf.xreak.top,cf.3666888.xyz"
  echo "  ${C_YELLOW}⚠ Zero Trust 里要有一条路由: $SUB_DOMAIN -> http://127.0.0.1:$SUB_PORT, 见 $WORKDIR/ROUTES.md${C_RESET}"
else
  echo ""
  echo "${C_YELLOW}⚠ 订阅 (公网): 未设置 SUB_DOMAIN, 只有面板本地订阅可用${C_RESET}"
  echo "  如需公网订阅, 重新部署时加上 SUB_DOMAIN=<订阅子域名> SUB_PORT=18080"
  echo "  例如: SUB_DOMAIN=sub.ahstshu.eu.cc"
fi
if is_true "$ENABLE_DIRECT"; then
  echo ""
  echo "${C_YELLOW}⚠ 直连节点 (自签名证书, 客户端需 allowInsecure=1, 仅作备用):${C_RESET}"
  # Direct links are the raw.txt lines without a tunnel remark
  # (丨Xray丨 / 丨Singbox丨); the VMess link's remark is base64-encoded
  # inside the link, so grep '丨直连丨' would miss it.
  grep -vE '丨(Xray|Singbox)丨' "$WORKDIR/sub/raw.txt" 2>/dev/null || true
fi
echo ""
echo "原生节点 (可直接复制到客户端):"
[ -f "$WORKDIR/sub/raw.txt" ] && cat "$WORKDIR/sub/raw.txt"
sep
echo ""
ok "部署完成. 面板: http://127.0.0.1:8080 (via ssh -L 8080:127.0.0.1:8080)  Xray: $XRAY_DOMAIN:$XRAY_PORT  Sing-box: $SINGBOX_DOMAIN:$SINGBOX_PORT"
